mapper.select:
select 
from evaluation_organization_mappings eom
join users u on u.user_id = eom.user_id
left join korus_personnel_snapshots kps on kps.employee_no = u.employee_no
join organizations o on o.organization_code = eom.organization_code
where eom.user_id = #{userId}
  and eom.organization_code = #{organizationCode}
  and eom.business_type = #{businessType}
